using System;using System.Collections.Generic;using System.Reflection;using UnityEngine;
public sealed class P3SmokeExecutionResult{public bool Passed=true;public List<string> Tests=new List<string>();public List<string> Logs=new List<string>();public List<string> Errors=new List<string>();}
public static class P3SmokeExecutionService{public static P3SmokeExecutionResult Execute(IEnumerable<string> names){var r=new P3SmokeExecutionResult();Application.LogCallback h=(c,s,t)=>{r.Logs.Add("["+t+"] "+c);if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert){r.Passed=false;r.Errors.Add(c);}};Application.logMessageReceived+=h;try{foreach(var name in names){r.Tests.Add(name);try{var split=name.LastIndexOf('.');if(split<1)throw new InvalidOperationException("Invalid registered test name");Type type=null;foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){type=a.GetType(name.Substring(0,split));if(type!=null)break;}var method=type?.GetMethod(name.Substring(split+1),BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);if(method==null)throw new MissingMethodException(name);method.Invoke(null,null);}catch(Exception e){r.Passed=false;r.Errors.Add((e.InnerException??e).Message);}}}finally{Application.logMessageReceived-=h;}return r;}}
